static public File allocateFile(File dir, String name) {
    if (dir == null) throw new IllegalArgumentException("dir is null");
    if (name == null) throw new IllegalArgumentException("name is null");
    // strip query
    int q = name.indexOf('?');
    if (q > 0) {
        name = name.substring(0, q);
    }
    // normalize name: remove any path traversal components
    // reject if contains separator or ".."
    if (name.contains("/") || name.contains("\\") || name.contains("..")) {
        throw new IllegalArgumentException("Invalid file name");
    }
    try {
        File canonicalDir = dir.getCanonicalFile();
        File file = new File(canonicalDir, name);
        // ensure canonical path is within dir
        File canonicalFile = file.getCanonicalFile();
        if (!canonicalFile.getPath().startsWith(canonicalDir.getPath() + File.separator) &&
            !canonicalFile.equals(canonicalDir)) {
            throw new IllegalArgumentException("Resulting file is outside the target directory");
        }
        // handle duplicate names
        int dot = name.lastIndexOf('.');
        String prefix = dot < 0 ? name : name.substring(0, dot);
        String suffix = dot < 0 ? "" : name.substring(dot);
        int index = 2;
        while (canonicalFile.exists()) {
            String newName = prefix + "-" + index++ + suffix;
            // repeat validation for newName (no separators, etc.)
            file = new File(canonicalDir, newName);
            canonicalFile = file.getCanonicalFile();
        }
        // ensure parent directories exist
        File parent = canonicalFile.getParentFile();
        if (parent != null && !parent.exists()) {
            if (!parent.mkdirs()) {
                throw new IllegalStateException("Failed to create directories for " + parent);
            }
        }
        return canonicalFile;
    } catch (IOException e) {
        throw new IllegalStateException("Failed to allocate file", e);
    }
