import javax.ws.rs.ext.RuntimeDelegate;

public class MediaTypeHeaderDelegate implements RuntimeDelegate.HeaderDelegate {
    // other methods ...

    /**
     * Validates that a string conforms to the HTTP token definition as per RFC 7230.
     * This method is used to validate the major and subtype components of a media type.
     * Only the characters defined as "tchar" are allowed:
     *   ! # $ % & ' * + - . ^ _ ` | ~ 0-9 A-Z a-z
     * All control characters, whitespace, delimiters and any non‑ASCII characters are rejected.
     *
     * @param str the string to validate
     * @return {@code true} if the string consists solely of allowed token characters; {@code false} otherwise
     */
    protected static boolean isValid(String str) {
        if (str == null || str.isEmpty()) {
            return false;
        }

        // Fast lookup table for allowed ASCII token characters (tchar)
        // Initialized once on first use.
        final boolean[] allowed = TokenValidator.ALLOWED_TOKEN_CHARS;

        for (int i = 0; i < str.length(); i++) {
            char c = str.charAt(i);
            // Reject any non‑ASCII character (c > 127) or control character (c <= 31 or c == 127)
            if (c > 127 || c <= 31 || c == 127) {
                return false;
            }
            // ASCII range 0‑127: use the lookup table
            if (!allowed[c]) {
                return false;
            }
        }
        return true;
    }

    /**
     * Helper class that builds a static lookup table for the allowed token characters.
     * The table is created once and reused by {@link #isValid(String)}.
     */
    private static final class TokenValidator {
        private static final boolean[] ALLOWED_TOKEN_CHARS = new boolean[128];

        static {
            // tchar = "!" / "#" / "$" / "%" / "&" / "'" / "*" / "+" / "-" / "." /
            //        "^" / "_" / "`" / "|" / "~" / DIGIT / ALPHA
            for (char c = 'a'; c <= 'z'; c++) {
                ALLOWED_TOKEN_CHARS[c] = true;
            }
            for (char c = 'A'; c <= 'Z'; c++) {
                ALLOWED_TOKEN_CHARS[c] = true;
            }
            for (char c = '0'; c <= '9'; c++) {
                ALLOWED_TOKEN_CHARS[c] = true;
            }
            char[] extra = {
                '!', '#', '$', '%', '&', '\'', '*', '+', '-', '.', '^',
                '_', '`', '|', '~'
            };
            for (char c : extra) {
                ALLOWED_TOKEN_CHARS[c] = true;
            }
        }

        private TokenValidator() {
            // Prevent instantiation
        }
    }

    // other methods ...
}
