private static void decompress(final InputStream in, final byte[] out) throws IOException {
    int position = 0;
    final int total = out.length;
    while (position < total) {
        int n = in.read();
        if (n == -1) {
            throw new EOFException("Unexpected end of compressed data");
        }
        if (n > 128) {
            int count = n & 0x7f;
            int value = in.read();
            if (value == -1) {
                throw new EOFException("Unexpected end of compressed data while reading repeat value");
            }
            if (position + count > total) {
                throw new IOException("Decompressed data exceeds expected size");
            }
            for (int i = 0; i < count; i++) {
                out[position++] = (byte) value;
            }
        } else {
            int count = n;
            if (position + count > total) {
                throw new IOException("Decompressed data exceeds expected size");
            }
            for (int i = 0; i < count; i++) {
                int b = in.read();
                if (b == -1) {
                    throw new EOFException("Unexpected end of compressed data while reading literal bytes");
                }
                out[position++] = (byte) b;
            }
        }
    }
