private static final Logger logger = Logger.getLogger(WebUtils.class.getName());

public static String getContextPath(HttpServletRequest request) {
    if (request == null) {
        throw new IllegalArgumentException("HttpServletRequest must not be null");
    }

    // Decode the servlet container's context path (always present, never null)
    String rawContextPath = request.getContextPath();
    if (rawContextPath == null) {
        rawContextPath = "";
    }
    String decodedContextPath = decodeRequestString(request, rawContextPath);

    // Normalize to eliminate any relative path tricks
    String normalized = normalize(decodedContextPath);

    // Basic validation: must start with '/' or be empty and must not contain illegal characters
    if (!normalized.isEmpty() && !normalized.startsWith("/")) {
        logger.warning("Context path does not start with '/' after normalization: " + normalized);
        normalized = "";
    }
    if (normalized.contains("..") || normalized.contains(";") || normalized.contains("\0")) {
        logger.warning("Potentially unsafe context path detected and cleared: " + normalized);
        normalized = "";
    }

    // Treat root context as empty string
    if ("/".equals(normalized)) {
        normalized = "";
    }

    // If an include attribute is present, verify that it matches the calculated value.
    String includePath = (String) request.getAttribute(INCLUDE_CONTEXT_PATH_ATTRIBUTE);
    if (includePath != null) {
        String decodedInclude = decodeRequestString(request, includePath);
        String normalizedInclude = normalize(decodedInclude);
        if (!normalizedInclude.equals(normalized)) {
            logger.warning("Include context path differs from request context path; using safe value.");
        }
    }

    return normalized;
}
