     * Expands entries supplied by {@code supplier} into {@code targetDirectory}.
     *
     * @param supplier        provides the next readable {@link ArchiveEntry}
     * @param writer          writes entry data to an {@link OutputStream}
     * @param targetDirectory directory into which entries are extracted
     * @throws IOException if an I/O error occurs or a security check fails
     */
    private void expand(ArchiveEntrySupplier supplier,
                        EntryWriter writer,
                        File targetDirectory) throws IOException {

        // Resolve the target directory to its real (canonical) path once.
        final Path targetPath = targetDirectory.toPath().toRealPath(LinkOption.NOFOLLOW_LINKS);

        ArchiveEntry nextEntry = supplier.getNextReadableEntry();
        while (nextEntry != null) {

            // -----------------------------------------------------------------
            // 1. Validate the entry name.
            // -----------------------------------------------------------------
            final String entryName = nextEntry.getName();
            if (entryName == null) {
                throw new IOException("Archive entry name is null");
            }

            // Reject absolute paths (e.g., "/etc/passwd" or "C:\temp\file").
            final Path rawEntryPath = Paths.get(entryName);
            if (rawEntryPath.isAbsolute()) {
                throw new IOException("Absolute entry name not allowed: " + entryName);
            }

