import static java.util.Calendar.*;

public final class CronTab {

    // other methods ...

    /**
     * See {@link #ceil(long)}.
     *
     * This method modifies the given calendar and returns the same object.
     *
     * @throws RareOrImpossibleDateException if the date isn't hit in the 2 years after it indicates an impossible
     * (e.g. Jun 31) date, or at least a date too rare to be useful.
     */
    public Calendar ceil(Calendar cal) {
        // two‑year limit – used to decide when a date is “too rare / impossible”
        Calendar twoYearsFuture = (Calendar) cal.clone();
        twoYearsFuture.add(Calendar.YEAR, 2);

        // safeguard against pathological input that would otherwise cause an endless loop
        final int MAX_ITERATIONS = 10_000;          // generous upper bound for normal cron expressions
        int iteration = 0;

        OUTER:
        while (true) {
            // protect against runaway loops
            if (iteration++ > MAX_ITERATIONS) {
                throw new RareOrImpossibleDateException(
                        "Exceeded maximum adjustment iterations – possible infinite loop");
            }

            // if we have already passed the two‑year horizon, give up
            if (cal.compareTo(twoYearsFuture) > 0) {
                throw new RareOrImpossibleDateException();
            }

            // remember the state at the start of this outer pass – used to detect lack of progress
            long beforeMillis = cal.getTimeInMillis();

            for (CalendarField f : CalendarField.ADJUST_ORDER) {
                int cur = f.valueOf(cal);
                int next = f.ceil(this, cur);

                // already at the ceiling for this field – nothing to do
                if (cur == next) {
                    continue;
                }

                // any change in a higher field forces lower fields to be cleared
                for (CalendarField l = f.lowerField; l != null; l = l.lowerField) {
                    l.clear(cal);
                }

                if (next < 0) {
                    // roll the field up; if rollUp does not change the calendar we are stuck → abort
                    long rollBefore = cal.getTimeInMillis();
                    f.rollUp(cal, 1);
                    if (cal.getTimeInMillis() == rollBefore) {
                        throw new RareOrImpossibleDateException(
                                "Roll‑up of field " + f + " made no progress");
                    }
                    // set to the first valid value for this field
                    f.setTo(cal, f.first(this));
                    // restart the whole adjustment process
                    continue OUTER;
                } else {
                    // set to the calculated next value
                    f.setTo(cal, next);
                    // some fields require a full re‑evaluation after being modified
                    if (f.redoAdjustmentIfModified) {
                        continue OUTER;
                    }
                }
            }

            // if we reach this point all fields are valid – but double‑check that we actually moved forward
            long afterMillis = cal.getTimeInMillis();
            if (afterMillis == beforeMillis) {
                // no progress was made; treat it as an impossible/rare date to avoid infinite looping
                throw new RareOrImpossibleDateException(
                        "No calendar progress after adjustment – possible infinite loop");
            }

            // successful adjustment
            return cal;
        }
    }

    // other methods ...

}
