        Class<?> type = getDocumentType();          // the type the caller expects
        Exception cause = null;

        /* -------------------------------------------------
         * 1) Try the standard Camel type conversion first.
         * ------------------------------------------------- */
        if (type != null) {
            try {
                answer = exchange.getContext().getTypeConverter().convertTo(type, exchange, body);
            } catch (Exception e) {
                cause = e; // remember the exception – we may need to re‑throw it later
            }
        }

        /* -------------------------------------------------
         * 2) If conversion failed, handle raw XML safely.
         * ------------------------------------------------- */
        if (answer == null) {
            InputStream is = null;

            if (body instanceof WrappedFile) {
                // Convert the wrapped file to an InputStream (e.g. a file on disk)
                is = exchange.getContext().getTypeConverter().convertTo(InputStream.class, exchange, body);
            } else if (body instanceof String) {
