         * 3) Fallback handling when no specific type is requested.
         * ------------------------------------------------- */
        if (type == null && answer == null) {
            answer = body; // no conversion requested – return the original object
        } else if (answer == null) {
            // Conversion failed – re‑throw the original cause or a generic exception
            if (cause != null) {
