        int fromPart = i < fromArr.length ? parseComponent(fromArr[i]) : 0;
        int toPart = i < toArr.length ? parseComponent(toArr[i]) : 0;
        if (fromPart != toPart) {
            return Integer.compare(fromPart, toPart);
        }
    }
    return 0;
}

private static int parseComponent(String s) {
    if (s == null) {
        return 0;
