        scheme = scheme.toLowerCase(Locale.ROOT);
        // Allow only safe schemes
        if (!Arrays.asList("http","https","ftp","mailto","tel").contains(scheme)) {
            // Disallow javascript:, data:, vbscript:, etc.
            return "";
