            factory.setProperty(XMLInputFactory.IS_SUPPORTING_EXTERNAL_ENTITIES, Boolean.FALSE);
        } catch (IllegalArgumentException e) {
            // Wrap in XMLStreamException to keep the method signature consistent.
            throw new XMLStreamException("Failed to configure XMLInputFactory securely (XXE protection).", e);
